{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C36", "C60", "C70", "C75", "C85"],
  "contradictory_card_ids": ["C02", "C04", "C23", "C33", "C50", "C63"],
  "prediction_basis_card_ids": ["C36", "C60", "C70", "C75", "C85"],
  "claims": [
    {
      "claim": "The query is an unPEGylated 4,5-epoxymorphinan with 6-keto and 14-hydroxy groups, the naloxone-like scaffold that C36 reports has poorer oral bioavailability than PEGylated naloxegol because glucuronidation is only a minor clearance route for naloxegol.",
      "card_ids": ["C36"]
    },
    {
      "claim": "C60 reports pentazocine F = 0.18 ± 0.05 in healthy controls, an affirmative measured value below the 20% threshold for a high-first-pass opioid; the cirrhosis records show higher values arise from reduced first-pass metabolism and do not transfer to the non-cirrhotic query.",
      "card_ids": ["C60", "C07", "C13"]
    },
    {
      "claim": "L3 records show oral naltrexone, which shares the 6-keto and 14-hydroxy morphinan scaffold, is converted to 6-β-naltrexol on first pass with metabolite Cmax of 20.4 pg/mL fasted and 64.4 pg/mL fed, consistent with extensive first-pass metabolism of this scaffold.",
      "card_ids": ["C70", "C75", "C85"]
    },
    {
      "claim": "Morphine L3 AUC records of 383-440 ng·h/mL show measurable oral exposure for a related N-methyl morphinan, but no F value is provided and morphine lacks the 6-keto and 14-hydroxy liabilities, so these records are neutral for the query.",
      "card_ids": ["C76", "C81", "C111", "C114"]
    },
    {
      "claim": "Codeine F = 80.5% (C04) and codeine relative bioavailability values of 50-55% (C23, C33, C50, C63) are less transferable because codeine lacks the 6-keto and 14-hydroxy groups.",
      "card_ids": ["C04", "C23", "C33", "C50", "C63"]
    },
    {
      "claim": "Naloxegol F = 0.90 (C02) is not transferable because PEGylation confers its oral bioavailability (C53, C57), which the query lacks.",
      "card_ids": ["C02", "C53", "C57"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C70", "C75", "C85"]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C76", "C81", "C111", "C114"]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "not_applicable",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C67", "C73", "C78", "C80", "C88", "C92", "C93", "C97", "C99", "C102", "C107", "C108", "C112", "C113", "C115"]
    }
  ],
  "evidence_gaps": [
    "No direct measured absolute oral bioavailability for the query molecule is provided.",
    "L3 records provide AUC and Cmax values without matched IV comparators, so no F can be derived from them.",
    "The low-F inference relies on structural analogy to naloxone and naltrexone and on the pentazocine control rather than a direct query measurement.",
    "No query-specific solubility, permeability, efflux, or first-pass metabolism data are supplied.",
    "Transfer from pentazocine (benzomorphan) and from naltrexone or naloxone (different N-substituents) to the N-methyl query is indirect."
  ],
  "decision_summary": "L3 oral exposure records are mostly not applicable (ethinylestradiol contraceptive PK) or neutral (morphine AUC without F); the naltrexol metabolite records mildly support extensive first-pass metabolism of the 6-keto and 14-hydroxy morphinan scaffold. The prior low prediction is kept: affirmative sub-20% evidence (pentazocine control F = 0.18 and the naloxone-like scaffold's poorer oral bioavailability relative to PEGylated naloxegol) supports F below 20% for the query."
}

